INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-04' FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Voluntary B2G issuance, no B2B mandate — but a real 2027 B2C sales-reporting revival in progress', 'This deep-dive page reflects publicly available guidance and reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. The Czech Republic has no confirmed timetable for a domestic B2B or B2G-issuance e-invoicing mandate as of this writing, and EET 2.0''s Senate passage and presidential signature were still pending — confirm current status directly with the Ministry of Finance or Ministry of Regional Development before building against it.', 'The Czech Republic completed a modest, receiving-only B2G e-invoicing rollout by October 2016 and has never proposed a domestic B2B mandate. What makes this country''s story worth tracking isn''t the invoicing side at all, though: a revived Electronic Registration of Sales regime (EET 2.0) — real-time reporting of in-person B2C sales — has already passed the Chamber of Deputies and is headed for the Senate and presidential signature, with a confirmed effective date of 1 January 2027. The one firm date that applies regardless of any of this remains the EU-wide ViDA cross-border floor of 1 July 2030.', 'Where e-invoices are exchanged with Czech public bodies, the accepted formats are EDIFACT, UBL 2.1, and the national ISDOC standard, typically via the Národní elektronický nástroj (NEN) portal — no clearance or real-time approval step of any kind.', 'The only enforceable e-invoicing obligation in the Czech Republic today runs one direction: public contracting authorities (central, regional, and local) must accept and process compliant e-invoices from suppliers who choose to send one. Nothing requires a supplier to actually send one, and there is no B2B mandate at all. Separately — and this is the genuinely live development — EET 2.0 will require real-time reporting of in-person B2C sales from 1 January 2027, a point-of-sale reporting duty rather than an invoicing mandate.', 'With no domestic B2B or B2G-issuance mandate in force or scheduled, most businesses'' relevant work is split two ways: readiness for e-invoicing (understanding that the receiving obligation exists on the government side only) and, if you run in-person retail, hospitality, or services, actual preparation for EET 2.0''s real-time sales-reporting requirement arriving in 2027.', 'There is no domestic e-invoicing penalty regime in the Czech Republic today, for the simple reason that there is no domestic e-invoicing mandate for suppliers to fail to comply with. EET 2.0 is a separate matter: its point-of-sale sales-reporting duty carries penalties of up to CZK 500,000 for non-compliance once it takes effect — a real fine, but for a sales-reporting failure, not an invoicing one.', 'The Czech Republic transposed EU Directive 2014/55/EU via Act No. 134/2016 Coll. on Public Procurement (Section 221), requiring public contracting authorities to accept EN 16931-compliant e-invoices from 1 October 2016, in EDIFACT, UBL 2.1, or the national ISDOC format via the NEN portal. Issuance by suppliers has remained voluntary throughout, and no domestic B2B mandate has ever been proposed. Separately, a revived Electronic Registration of Sales regime (EET 2.0) — real-time reporting of in-person B2C sales, not a B2B invoicing mandate — has passed the Chamber of Deputies and awaits Senate passage and presidential signature, with a confirmed effective date of 1 January 2027, an exemption for small flat-rate-tax entrepreneurs under CZK 1,000,000 annual revenue, and penalties of up to CZK 500,000. The EU''s ViDA cross-border B2B e-invoicing and reporting mandate is confirmed EU law from 1 July 2030, regardless of any future Czech domestic decision.', '🇨🇿' FROM countries WHERE name_en = 'Czech Republic';
