INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Standard", "EN 16931, the European Standard on e-invoicing"], ["Accepted syntaxes", "EDIFACT, UBL 2.1, and the national ISDOC standard"], ["Legal basis", "Act No. 134/2016 Coll. on Public Procurement (Section 221), transposing EU Directive 2014/55/EU"], ["B2B today", "No mandate; bilateral agreement between trading partners where used at all"]]', 'ISDOC is the one genuinely Czech element here — a national XML invoice format that predates the EU directive — but it sits alongside EN 16931/UBL 2.1 rather than replacing it; nothing requires a business to use it specifically.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["B2G receiving", "No registration needed — this is an obligation on public contracting authorities, not suppliers"], ["Voluntary issuance channel", "Národní elektronický nástroj (NEN) portal"], ["Governing body", "Ministry of Regional Development (NEN platform); Ministry of Finance (tax policy)"], ["B2B today", "No registration exists — nothing to register for"]]', 'Because there''s no issuance mandate, there''s genuinely no registration step for a typical business to complete — the obligation enacted so far applies entirely to the receiving side, and it sits with public contracting authorities, not suppliers.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Where used", "Full EN 16931 core invoice model, or ISDOC''s own field set"], ["Mandatory fields", "None specified beyond the standard itself, since there''s no domestic mandate defining additional requirements"], ["Archiving", "Standard Czech record-keeping requirements apply regardless of format"]]', 'Without a domestic mandate specifying additional national fields, a Czech e-invoice is simply a standard EN 16931 or ISDOC document — nothing extra to learn beyond picking a format both sides can read.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Invoicing model", "No clearance or real-time invoice-reporting regime of any kind"], ["B2G channel", "NEN portal, for suppliers who choose to send electronically"], ["B2B channel", "Bilateral agreement, if used at all"], ["EET 2.0 (separate)", "Real-time point-of-sale reporting to the Tax Administration, from 2027 -- not an invoicing channel"]]', 'It''s worth keeping these two systems mentally separate: nothing about EET 2.0 changes how an invoice moves between businesses, because EET 2.0 isn''t about invoices at all -- it''s about reporting the underlying sale at the till.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s actually mandatory today', '[["Public contracting authorities", "Must accept and process compliant e-invoices (since 1 October 2016)"], ["Suppliers to government", "No issuance obligation"], ["Private businesses (B2B/B2C invoicing)", "No obligation of any kind"], ["In-person B2C sales (from 2027)", "Real-time reporting under EET 2.0 -- a sales-recording duty, not an invoicing one"]]', 'It''s worth being precise here: the Czech Republic has never mandated that anyone send an e-invoice -- only that certain public bodies be capable of accepting one, and, separately and from 2027, that in-person sales get reported in real time.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'EET 2.0 -- a real but different obligation', '[["What it covers", "In-person B2C sales -- cash, card, and QR-code payments"], ["Effective date", "1 January 2027 (confirmed in the passed bill)"], ["Exemption", "Small flat-rate-tax entrepreneurs under CZK 1,000,000 annual revenue may pay a surcharge for exemption"], ["Legislative status", "Passed the Chamber of Deputies; Senate passage and presidential signature still pending"]]', 'This is the one entry on this page worth watching for a real signal on timing -- the effective date is written into the bill the lower house already passed, but the Senate and President still have to sign off before it''s fully law.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🤝 No domestic e-invoicing penalty regime', NULL, NULL, 'There is no domestic penalty for failing to issue an e-invoice in the Czech Republic today, for the straightforward reason that no law requires it. The only enforceable obligation -- receiving compliant invoices -- sits with public contracting authorities, not suppliers.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💰 EET 2.0''s penalties are real -- but for sales reporting, not invoicing', NULL, NULL, 'Once EET 2.0 takes effect, non-compliance with the real-time sales-reporting duty carries penalties of up to CZK 500,000. This is a genuine, sourced figure -- but it''s a fine for failing to report a sale, not for failing to issue an e-invoice. Don''t conflate the two when assessing exposure.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇪🇺 The approaching EU floor', NULL, NULL, 'Regardless of whether the Czech Republic ever enacts its own domestic B2B mandate, ViDA''s cross-border requirement is confirmed EU law from 1 July 2030 -- every Czech business doing intra-EU B2B trade will need EN 16931-compliant e-invoicing and digital reporting for those transactions.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Understand what''s actually mandatory for invoicing (very little)', 'Only public contracting authorities'' receiving capability is required by law -- there''s no issuance obligation for suppliers, and no B2B mandate of any kind today.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you run in-person retail, hospitality, or services, prepare for EET 2.0', 'Real-time reporting of cash, card, and QR-code sales becomes mandatory from 1 January 2027 -- a separate obligation from invoicing, but a real one with penalties up to CZK 500,000.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply Czech public bodies, consider voluntary e-invoicing', 'Sending structured e-invoices via NEN in EDIFACT, UBL 2.1, or ISDOC may speed up processing even though it isn''t required -- a low-cost way to get ahead of a future mandate.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for the confirmed 2030 cross-border floor regardless', 'Every business doing intra-EU B2B trade needs EN 16931 e-invoicing and digital reporting capability from 1 July 2030 -- this date is fixed by EU directive, not Czech discretion.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Czech Republic';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for Senate passage and presidential signature on EET 2.0', 'The Chamber of Deputies has passed the bill and its 1 January 2027 date, but the Senate and President Petr Pavel still need to sign off before it''s fully enacted.');
